using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared setup for evaluation scenarios: telemetry, quality judges, and compare mode.
/// </summary>
public static class EvalSetup
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates a <see cref="ReportingConfiguration"/> wired for telemetry export,
    /// quality evaluation, and baseline comparison.
    /// </summary>
    public static ReportingConfiguration CreateConfiguration(string scenarioName)
    {
        var storage = new DiskBasedResultStorage(StoragePath);

        // Quality evaluators
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(
            storage,
            evaluators,
            chatConfiguration: null,
            scenarioName: scenarioName,
            enableCompareMode: true);
    }

    /// <summary>
    /// Configures OpenTelemetry tracing for eval runs and exports via OTLP.
    /// </summary>
    public static TracerProvider BuildTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Coach")
            .AddOtlpExporter()
            .Build()!;
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

[TestClass]
public sealed class CoachEvalTests
{
    private static TracerProvider? s_telemetry;
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_telemetry = EvalSetup.BuildTelemetry();
        s_config = EvalSetup.CreateConfiguration(scenarioName: nameof(CoachEvalTests));
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        s_telemetry?.Dispose();
    }

    [TestMethod]
    public async Task Telemetry_TracesEmitted()
    {
        // Validates that the coach emits OpenTelemetry traces during a turn.
        await using var scenario = await s_config!.CreateScenarioRunAsync("telemetry-basic");

        var response = new ChatMessage("assistant", "Sample traced response.");
        scenario.Record(response);

        // No quality assertions — telemetry mode only verifies spans are exported.
        Assert.IsNotNull(response.Text);
    }

    [TestMethod]
    public async Task Quality_ResponseMeetsThresholds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("quality-coaching");

        var request = new ChatMessage("user", "How do I improve my running pace?");
        var response = new ChatMessage("assistant",
            "To improve your running pace, focus on interval training, "
            + "maintain consistent mileage, and incorporate tempo runs into your weekly schedule.");

        scenario.Record(request, response);
        await scenario.EvaluateAsync(request, response);

        // Assert quality scores exceed minimum thresholds.
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric)
            {
                Assert.IsTrue(numeric.Value >= 3.0,
                    $"Metric '{numeric.Name}' scored {numeric.Value}, below threshold 3.0");
            }
        }
    }

    [TestMethod]
    public async Task Compare_BaselineRegression()
    {
        // Compare mode: results are persisted to disk so subsequent runs
        // can be diffed against the baseline via the reporting tool.
        await using var scenario = await s_config!.CreateScenarioRunAsync("compare-baseline");

        var request = new ChatMessage("user", "What stretches help prevent injury?");
        var response = new ChatMessage("assistant",
            "Dynamic stretches before running and static stretches afterward "
            + "help prevent common injuries like shin splints and IT band syndrome.");

        scenario.Record(request, response);
        await scenario.EvaluateAsync(request, response);

        // Comparison is done offline via `dotnet eval report --compare`.
        // Here we just ensure the run completes and metrics are stored.
        var results = scenario.GetEvaluationResults();
        Assert.IsTrue(results.Any(), "Expected at least one evaluation metric to be recorded.");
    }
}

